The <b>Select operation</b> in Relational Algebra is used to <b>filter rows (tuples)</b> from a relation
that satisfy a given condition called a <b>predicate</b>. It does not change the attributes (columns);
it only reduces the number of tuples (rows).

\begin{align*}
\Bigl\{ t \;\Big|\; & 
\exists s \in \text{instructor} \;\big(
    t[\text{name}] = s[\text{name}] \;\wedge\; \\
& \exists u \in \text{department} \;\big(
        u[\text{dept\_name}] = s[\text{dept\_name}] \;\wedge\; 
        u[\text{building}] = 'Watson'
    \big)
\big)
\Bigr\}
\end{align*}

\begin{align*}
\Bigl\{ t \;\Big|\; &
\big( \exists s \in \text{section} \; ( 
    t[\text{course\_id}] = s[\text{course\_id}] \;\wedge\; 
    s[\text{semester}] = 'Fall' \;\wedge\; 
    s[\text{year}] = 2017 
) \big) \\
& \vee 
\big( \exists u \in \text{section} \; ( 
    t[\text{course\_id}] = u[\text{course\_id}] \;\wedge\; 
    u[\text{semester}] = 'Spring' \;\wedge\; 
    u[\text{year}] = 2018 
) \big)
\Bigr\}
\end{align*}

\begin{align*}
\Bigl\{ t \;\Big|\; &
\exists s \in \text{section} \; (
    t[\text{course\_id}] = s[\text{course\_id}] \;\wedge\; 
    s[\text{semester}] = 'Fall' \;\wedge\; 
    s[\text{year}] = 2017
) \\
& \wedge \;
\exists u \in \text{section} \; (
    t[\text{course\_id}] = u[\text{course\_id}] \;\wedge\; 
    u[\text{semester}] = 'Spring' \;\wedge\; 
    u[\text{year}] = 2018
)
\Bigr\}
\end{align*}

\begin{align*}
\Bigl\{ t \;\Big|\; &
\exists r \in \text{student} \; ( r[\text{ID}] = t[\text{ID}] ) \\
& \wedge \;
\forall u \in \text{course} \; \big(
    u[\text{dept\_name}] = 'Biology' \;\Rightarrow\; 
    \exists s \in \text{takes} \; (
        t[\text{ID}] = s[\text{ID}] \;\wedge\; 
        s[\text{course\_id}] = u[\text{course\_id}]
    ) 
\big)
\Bigr\}
\end{align*}
